<script setup lang="ts">
// Author by Lab | zefry. Read-only preview precedes an explicit owner command.
import { onBeforeUnmount, ref, watch } from 'vue';
import { locale } from '../i18n';
import WorkspaceIcon from './WorkspaceIcon.vue';
const props=defineProps<{business:Record<string,any>;busy:boolean;reason:string}>();
const emit=defineEmits<{command:[body:Record<string,unknown>]}>();
const tr=(id:string,en:string)=>locale.value==='id'?id:en;
const scopes=[['transactions','Transaksi kasir & shift','POS transactions & shifts'],['products','Produk, kategori & catatan stok','Products, categories & stock records'],['inventory','Stok (jumlah menjadi nol)','Inventory (quantities become zero)'],['finance','Pembelian & keuangan','Purchasing & finance'],['partners','Pelanggan & pemasok','Customers & suppliers'],['people','Data SDM (akun masuk tetap ada)','HR records (login accounts remain)'],['settings','Preferensi bisnis & POS','Business & POS preferences'],['all','Seluruh data operasional bisnis','All business operational data']];
const scope=ref('transactions');const plan=ref<Record<string,any>|null>(null);const loading=ref(false);const error=ref('');const confirmation=ref('');const reviewed=ref(false);const offline=ref(false);const backup=ref(false);let active:AbortController|null=null;
function clear(){active?.abort();plan.value=null;confirmation.value='';reviewed.value=false;offline.value=false;backup.value=false;error.value=''}
watch(()=>props.business.id,clear);watch(scope,clear);onBeforeUnmount(()=>active?.abort());
async function preview(){if(loading.value||props.busy)return;clear();loading.value=true;const request=new AbortController();active=request;const timer=setTimeout(()=>request.abort(),20000);try{const response=await fetch(`/platform/control/businesses/${encodeURIComponent(props.business.id)}/reset-preview?scope=${scope.value}`,{credentials:'same-origin',redirect:'error',headers:{Accept:'application/json'},signal:request.signal});if(response.status===401||response.status===419){location.assign('/owner-login?reason=session-expired');return}if(!response.ok||request.signal.aborted)throw Error();const result=await response.json();if(request.signal.aborted)throw Error();plan.value=result}catch{error.value=tr('Pratinjau belum selesai. Muat ulang dan coba lagi. Belum ada data dihapus.','Preview failed or timed out. Reload and retry. No data was deleted.')}finally{clearTimeout(timer);if(active===request)active=null;loading.value=false}}
function reset(){if(!plan.value||plan.value.blocked.length||!reviewed.value||!offline.value||!backup.value||confirmation.value!=='RESET '+props.business.id||props.reason.trim().length<12||props.busy)return;emit('command',{action:'business.reset_data',id:props.business.id,version:Number(props.business.version),scope:scope.value,review_digest:plan.value.review_digest,reviewed:true,offline_reconciled:true,backup_acknowledged:true,confirmation:confirmation.value,reason:props.reason})}
const block=(code:string)=>({RESET_SUSPEND_BUSINESS_FIRST:tr('Tangguhkan akun bisnis terlebih dahulu.','Suspend this business first.'),RESET_WAIT_FOR_REQUESTS_TO_DRAIN:tr('Tunggu 60 detik setelah penangguhan, lalu tinjau ulang.','Wait 60 seconds after suspension, then preview again.'),RESET_CLOSE_OR_RECOVER_ACTIVE_SHIFTS:tr('Tutup atau pulihkan semua shift aktif terlebih dahulu.','Close or recover every active shift first.'),RESET_FINANCE_DEPENDS_ON_PARTNERS:tr('Data pembelian/keuangan masih menggunakan pelanggan atau pemasok. Reset keuangan dahulu atau pilih seluruh data.','Purchasing/finance still references these partners. Reset finance first or select all data.')} as Record<string,string>)[code]??code;
</script>
<template><section class="reset-panel"><h3><WorkspaceIcon name="database"/>{{tr('Reset data akun bisnis','Reset business data')}}</h3><p>{{tr('Hapus hanya data pada bisnis ini. Akun bisnis, pengguna, peran, TOTP, audit platform, pengaturan SMTP dan website tetap dipertahankan. Akun tetap ditangguhkan sampai Anda mengaktifkannya kembali.','Delete data for this business only. The business account, users, roles, TOTP, platform audit, SMTP and website configuration are preserved. The account stays suspended until you resume it.')}}</p><label>{{tr('Cakupan penghapusan','Deletion scope')}}<select v-model="scope" :disabled="busy||loading"><option v-for="s in scopes" :key="s[0]" :value="s[0]">{{tr(s[1],s[2])}}</option></select></label><button type="button" :disabled="busy||loading" @click="preview">{{loading?tr('Menyiapkan pratinjau…','Preparing preview…'):tr('Tinjau dampak reset','Preview reset impact')}}</button><p v-if="error" role="alert">{{error}}</p><div v-if="plan" class="review"><p v-for="code in plan.blocked" :key="code" role="alert"><b>{{block(code)}}</b><code>{{code}}</code></p><div class="scroll"><table><thead><tr><th>{{tr('Tabel data','Data table')}}</th><th>{{tr('Baris','Rows')}}</th><th>{{tr('Tindakan','Action')}}</th></tr></thead><tbody><tr v-for="entry in plan.entries" :key="entry.table"><td>{{entry.table}}</td><td>{{entry.rows}}</td><td>{{entry.action==='delete'?tr('Hapus','Delete'):tr('Nolkan stok terkelola','Zero tracked stock')}}</td></tr></tbody></table></div><p>{{tr('Semua otorisasi offline lama akan dicabut. Struk dan antrean Windows tetap ada, sehingga transaksi lama perlu direkonsiliasi dan tidak boleh dikirim sebagai transaksi baru.','All old offline leases will be invalidated. Windows receipts and queues remain, so old entries require reconciliation and must not be resubmitted as new transactions.')}}</p><label class="check"><input v-model="reviewed" type="checkbox" :disabled="busy"/>{{tr('Saya sudah meninjau seluruh cakupan dan jumlah data.','I reviewed the complete scope and row counts.')}}</label><label class="check"><input v-model="offline" type="checkbox" :disabled="busy"/>{{tr('Semua kasir berhenti bertransaksi; antrean offline sudah diekspor atau direkonsiliasi.','All registers stopped trading; offline queues were exported or reconciled.')}}</label><label class="check"><input v-model="backup" type="checkbox" :disabled="busy"/>{{tr('Saya memahami data akan dihapus. Salinan terenkripsi dibuat di penyimpanan privat sebelum reset; pemulihan memerlukan operator.','I understand data will be deleted. An encrypted private copy is created before reset; restoration requires an operator.')}}</label><label>{{tr('Ketik persis untuk mengonfirmasi:','Type exactly to confirm:')}} <code>RESET {{business.id}}</code><input v-model="confirmation" :disabled="busy" autocomplete="off" spellcheck="false"/></label><p>{{tr('Isi catatan tindakan di atas minimal 12 karakter. Jika data berubah setelah pratinjau, reset ditolak dan harus ditinjau ulang.','Enter an action note of at least 12 characters above. If data changes after preview, reset is rejected and must be previewed again.')}}</p><button class="confirm" type="button" :disabled="busy||plan.blocked.length>0||!reviewed||!offline||!backup||confirmation!=='RESET '+business.id||reason.trim().length<12" @click="reset">{{tr('Konfirmasi penghapusan data terpilih','Confirm deletion of selected data')}}</button></div></section></template>
<style scoped>
.reset-panel{margin-top:28px;padding:24px;border:2px solid #99B7FC;border-radius:20px;background:#FFFFFF;color:#202020;box-shadow:0 10px 30px #1B1B390A}.reset-panel h3{font-size:24px;display:flex;align-items:center;gap:10px;color:#1B1B39;margin:0 0 14px}.reset-panel p{font-size:16px;line-height:1.65}.reset-panel label{display:flex;flex-direction:column;gap:10px;font-size:16px;margin:18px 0}.reset-panel input,.reset-panel select{font:inherit;padding:12px;border:1px solid #99B7FC;border-radius:12px;background:#FFFFFF;color:#202020;width:100%;box-sizing:border-box}.reset-panel .check{flex-direction:row;align-items:flex-start;line-height:1.6}.reset-panel .check input{width:20px;height:20px;flex-shrink:0;accent-color:#3965FA}.reset-panel button{font:600 16px system-ui;padding:12px 18px;border:1px solid #3965FA;border-radius:12px;background:#E9EBFF;color:#1B1B39;cursor:pointer}.reset-panel button.confirm{background:#1B1B39;color:#FFFFFF}.reset-panel button:disabled{opacity:.5;cursor:not-allowed}.reset-panel :focus-visible{outline:3px solid #3965FA;outline-offset:3px}.review{margin-top:20px}.scroll{overflow:auto}.reset-panel table{width:100%;border-collapse:collapse;font-size:14px;min-width:500px}.reset-panel th,.reset-panel td{padding:12px;border-bottom:1px solid #EDEDED;text-align:left}.reset-panel th{background:#E9EBFF;color:#1B1B39}.reset-panel code{display:block;overflow-wrap:anywhere;color:#1B1B39;font-size:14px}@media(max-width:700px){.reset-panel{padding:16px}.reset-panel h3{font-size:22px}}
</style>
